#!/usr/bin/env python3
"""
Round 220o (culprits), 17 October 2026. Needs round 219o.

The Rape row's counts after the repeat checks of every country.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 220o (17 October)\n\nNeeds round 219o (guards on its heading). No tiles patch. No app.js?v= bump.\nThe owner's rape.html in the maps repo is replaced by the latest build.\n\n- Repeat checks of every country without a registry: penal and children's\n  codes, UN Committee on the Rights of the Child documents, the Out of the\n  Shadows Index 2026 (indicator 2.3), Council of Europe Lanzarote replies\n  (2026). Rape row now: 118 national registries and vetting schemes outside\n  the US, 108 sub-national elsewhere, 68 countries a source says have none\n  (re-checked for newer laws and bills: Costa Rica and Czechia now have\n  registers by law, Germany and Russia work-with-children checks; bills\n  pending in Ecuador, Egypt, Guyana, BVI, Lithuania, Moldova, Peru,\n  Philippines), 24 countries with nothing either way, 711 US county\n  sheriffs, city police and district attorneys (from 22 OffenderWatch state\n  pages the owner saved), 79 links shown inside\n  the map.\n- Tests: the round 219o block updated.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round220o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 219o" not in h.read_text(encoding="utf-8"):
        sys.exit("round220o: round 219o must be applied first (round219o_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round220o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "pipeline/sitemaps/registry.json", check=False)
            sys.exit("round220o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round220o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
